include /etc/nginx/snippets/jigsaw-geo.conf;
limit_req_zone $binary_remote_addr zone=jigsaw_auth:10m rate=12r/m;
limit_req_zone $binary_remote_addr zone=jigsaw_api:10m rate=120r/s;
limit_req_zone $binary_remote_addr zone=jigsaw_create:10m rate=6r/m;
server {
    listen 80;
    listen [::]:80;
    server_name jigsawnook.online www.jigsawnook.online;
    location ^~ /.well-known/acme-challenge/ { root /var/www/acme; }
    location ~ ^/baidu_verify_[A-Za-z0-9._-]+\.html$ { root /var/www/baidu-verify; }
    location / { return 301 https://jigsawnook.online$request_uri; }
}
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name www.jigsawnook.online;
    ssl_certificate /etc/letsencrypt/live/jigsawnook.online/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/jigsawnook.online/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;
    location ~ ^/baidu_verify_[A-Za-z0-9._-]+\.html$ { root /var/www/baidu-verify; }
    location / { return 301 https://jigsawnook.online$request_uri; }
}
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name jigsawnook.online;
    ssl_certificate /etc/letsencrypt/live/jigsawnook.online/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/jigsawnook.online/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;
    include /etc/nginx/snippets/tarotquill-realip.conf;
    include /etc/nginx/snippets/jigsaw-proxy.conf;
    client_max_body_size 16k;
    # Avoid recording room invite links, feedback tokens or account parameters.
    access_log off;
    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy no-referrer always;
    add_header Strict-Transport-Security "max-age=31536000" always;
    # Application metadata and middleware control public/private indexing.
    error_page 429 = @jigsaw_rate_limit;
    location @jigsaw_rate_limit {
        default_type application/json;
        add_header Retry-After 60 always;
        add_header Cache-Control no-store always;
        add_header X-Content-Type-Options nosniff always;
        return 429 '{"error":"Too many requests. Please try again shortly."}';
    }
# Add these locations only to the jigsawnook.online HTTPS server block.
location = /taptap-play { return 302 /taptap-play/; }
location ^~ /taptap-play/ {
    proxy_pass http://127.0.0.1:3291/;
    proxy_set_header X-Jigsaw-Client-IP $remote_addr;
    add_header X-Robots-Tag "noindex, nofollow" always;
}
location ^~ /h5/ {
    access_log /var/log/nginx/jigsaw-h5-diagnostic.log jigsaw_h5_diagnostic;
    client_max_body_size 16m;
    proxy_pass http://127.0.0.1:3291;
    proxy_set_header X-Jigsaw-Client-IP $remote_addr;
    proxy_read_timeout 70s;
    add_header X-Robots-Tag "noindex, nofollow" always;
}

    # Isolated mobile game API; PC and legacy H5 routes remain unchanged.
    location ^~ /h5-mobile-v3/ {
        client_max_body_size 3m;
        proxy_pass http://127.0.0.1:3292/h5/;
        proxy_set_header X-Jigsaw-Client-IP $remote_addr;
        proxy_read_timeout 70s;
        add_header X-Robots-Tag "noindex, nofollow" always;
    }

    location = /healthz { proxy_pass http://127.0.0.1:3103/api/health; }
    location = /api/feedback { client_max_body_size 16m; proxy_pass http://127.0.0.1:3103; }
    location ^~ /api/feedback/ { client_max_body_size 16m; proxy_pass http://127.0.0.1:3103; }
    location ^~ /api/auth/ {
        limit_req zone=jigsaw_auth burst=12 nodelay;
        limit_req_status 429;
        proxy_pass http://127.0.0.1:3103;
    }
    location = /api/user-images {
        client_max_body_size 2m;
        limit_req zone=jigsaw_create burst=3 nodelay;
        limit_req_status 429;
        proxy_pass http://127.0.0.1:3103;
    }
    location = /api/rooms {
        limit_req zone=jigsaw_create burst=6 nodelay;
        limit_req_status 429;
        proxy_pass http://127.0.0.1:3103;
    }
    location /api/ {
        limit_req zone=jigsaw_api burst=120 nodelay;
        limit_req_status 429;
        proxy_pass http://127.0.0.1:3103;
    }
    location ^~ /_next/static/ {
        root /srv/sites/jigsaw/current/dist/client;
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable";
        add_header X-Content-Type-Options nosniff;
    }
    location ~ "^/puzzles/[^/]+-(?:play|standard|thumbnail|optimized|compact)-[a-f0-9]{12}\.webp$" {
        root /srv/sites/jigsaw/current/dist/client;
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable";
        add_header X-Content-Type-Options nosniff;
    }
    location ~ "^/intro/hero-paper-coast-[a-f0-9]{12}\.webp$" {
        root /srv/sites/jigsaw/current/dist/client;
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable";
        add_header X-Content-Type-Options nosniff;
    }
    location ~ ^/baidu_verify_[A-Za-z0-9._-]+\.html$ { root /var/www/baidu-verify; }
    location / { proxy_pass http://127.0.0.1:3103; }
}
